25	// Maximal independent set (MIS) on a symmetric graph, computed with the
26	// round-based "lexicographically-first" algorithm.
27	//
28	// Every vertex is in one of three states, held in the flags array:
29	//   0 (UNDECIDED)  not yet placed in or out of the set,
30	//   1 (IN)         in the MIS,
31	//   2 (OUT)        excluded, because a neighbor is in the MIS.
32	//
33	// A round proceeds in three phases:
34	//   (a) the root set is every still-undecided vertex that has NO undecided
35	//       neighbor with a smaller vertex id.  Two root-set vertices can never be
36	//       adjacent (of an adjacent pair, the larger one sees the smaller one as an
37	//       undecided smaller neighbor), so the whole root set can be added to the
38	//       MIS at once.
39	//   (b) the root set is marked IN.
40	//   (c) an edgeMap out of the root set marks every undecided neighbor of a root
41	//       OUT.  Roots are already IN at that point, so cond() shields them.
42	// The undecided set shrinks every round -- the smallest undecided id is always
43	// a root -- so the loop terminates, and the result is exactly the set produced
44	// by the sequential greedy scan "visit vertices in increasing id order, add the
45	// vertex if no neighbor has already been added".
46	//
47	// The "no smaller undecided neighbor" test is done with countOutNgh rather than
48	// by walking a neighbor array, so the code also works on compressed (Ligra+)
49	// vertices.
50	#include "ligra.h"
51	#include <fstream>
52	
53	// Vertex states.
54	#define MIS_UNDECIDED 0
55	#define MIS_IN 1
56	#define MIS_OUT 2
57	
58	// Phase (a): is v a root, i.e. does v have no undecided neighbor with a
59	// smaller id?  Applied through vertexFilter to the undecided frontier.
60	template <class vertex>
61	struct MIS_Root_F {
62	  vertex* V;
63	  intE* flags;
64	  MIS_Root_F(vertex* _V, intE* _flags) : V(_V), flags(_flags) {}
65	  inline bool operator () (uintE v) {
66	    intE* fl = flags;
67	    // countOutNgh takes its predicate by reference, hence the named lambda.
68	    auto smallerUndecided = [&] (uintE src, uintE ngh) {
69	      return (ngh < src) && (fl[ngh] == MIS_UNDECIDED);
70	    };
71	    return V[v].countOutNgh(v, smallerUndecided) == 0;
72	  }
73	};
74	
75	// Phase (b): move a root into the MIS.
76	struct MIS_Add_F {
77	  intE* flags;
78	  MIS_Add_F(intE* _flags) : flags(_flags) {}
79	  inline bool operator () (uintE v) { flags[v] = MIS_IN; return 1; }
80	};
81	
82	// Phase (c): every undecided neighbor of a vertex in the MIS is excluded.
83	struct MIS_Exclude_F {
84	  intE* flags;
85	  MIS_Exclude_F(intE* _flags) : flags(_flags) {}
86	  inline bool update (uintE s, uintE d) { //Update
87	    flags[d] = MIS_OUT; return 1;
88	  }
89	  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
90	    return CAS(&flags[d],(intE)MIS_UNDECIDED,(intE)MIS_OUT);
91	  }
92	  //only undecided vertices can still be excluded
93	  inline bool cond (uintE d) { return flags[d] == MIS_UNDECIDED; }
94	};
95	
96	// Keeps the vertices that are still undecided at the end of a round.
97	struct MIS_Undecided_F {
98	  intE* flags;
99	  MIS_Undecided_F(intE* _flags) : flags(_flags) {}
100	  inline bool operator () (uintE v) { return flags[v] == MIS_UNDECIDED; }
101	};
102	
103	template <class vertex>
104	void Compute(graph<vertex>& GA, commandLine P) {
105	  const long n = GA.n;
106	  //flags[v] holds the state of v; everything starts out undecided
107	  intE* flags = newA(intE,n);
108	  {parallel_for(long i=0;i<n;i++) flags[i] = MIS_UNDECIDED;}
109	
110	  //the frontier always holds exactly the undecided vertices
111	  bool* undecided = newA(bool,n);
112	  {parallel_for(long i=0;i<n;i++) undecided[i] = 1;}
113	  vertexSubset Frontier(n,n,undecided);
114	
115	  long rounds = 0;   //number of root-set rounds
116	  long MISsize = 0;  //number of vertices placed in the MIS
117	  while(!Frontier.isEmpty()) {
118	    rounds++;
119	    // vertexFilter takes its argument by value and densifies the copy, so
120	    // materialize the dense array here to keep ownership in Frontier.
121	    Frontier.toDense();
122	    // (a) undecided vertices with no smaller undecided neighbor
123	    vertexSubset roots = vertexFilter(Frontier,MIS_Root_F<vertex>(GA.V,flags));
124	    // (b) the whole root set joins the MIS
125	    vertexMap(roots,MIS_Add_F(flags));
126	    MISsize += roots.numNonzeros();
127	    // (c) exclude the undecided neighbors of the new MIS vertices
128	    edgeMap(GA,roots,MIS_Exclude_F(flags),-1,no_output);
129	    roots.del();
130	    // (d) drop the vertices that were decided this round
131	    vertexSubset remaining = vertexFilter(Frontier,MIS_Undecided_F(flags));
132	    Frontier.del();
133	    Frontier = remaining;
134	  }
135	  Frontier.del();
136	
137	  cout << "MIS rounds: " << rounds << endl;
138	  cout << "MIS size: " << MISsize << endl;
139	
140	  //optionally dump the chosen vertices, one id per line, for verification
141	  string outFileName = P.getOptionValue("-outfile","");
142	  if(outFileName != "") {
143	    ofstream outFile(outFileName.c_str());
144	    if(outFile.is_open()) {
145	      for(long i=0;i<n;i++) if(flags[i] == MIS_IN) outFile << i << endl;
146	      outFile.close();
147	    } else cout << "MIS: could not open " << outFileName << endl;
148	  }
149	
150	  free(flags);
151	}
